  422: { note: "`IPCONFIG` este comanda reală, ușor de confundat cu distractorii inventați `WINCONFIG` și `IP_CONF`. Atenție la prefix și la underscore.", optionHighlights: { b: ["WINCONFIG"], c: ["IPCONFIG"], d: ["IP_CONF"] } },
