  438: { note: "Toate variantele au \"minim ... pană la destinație\", dar RIP folosește `Numărul minim de salturi`, nu `Timpul minim`.", optionHighlights: { a: ["Numărul minim de salturi"], c: ["Timpul minim"] } },
  440: { note: "Aproape identică cu varianta despre citirea poștei, însă aici serviciul `funcționează pe baza` tuturor protocoalelor (deci include și SMTP). Cealaltă cere doar citirea.", searchQuery: "postă electronică funcționează pe baza", stemHighlights: ["funcționează pe baza"] },
