  447: { note: "FE80::/10 este adresă `link local`, iar decoiul schimbă un cuvânt în `site local` (prefix diferit, FEC0::/10, depreciat).", optionHighlights: { b: ["link local"], c: ["site local"] } },
  450: { note: "Agentul SNMP `Răspunde` la interogări, iar decoiul spune `Solicită` informații, ceea ce este de fapt rolul managerului. Capcana inversează rolurile.", optionHighlights: { a: ["Solicită"], b: ["Răspunde"] } },
