  466: { note: "Același tipar de enunț ca la coderul de sursă sau de canal; aici se cere rolul \"blocului de criptare\" (confidențialitatea transmisiei).", searchQuery: "Care este rolul", stemHighlights: ["blocului de criptare"] },
  468: { note: "Variantele corectă și greșită sunt identice cuvânt cu cuvânt, diferă doar prin \"decriptare cu chei\" (corect) față de \"decriptare fără chei\".", optionHighlights: { a: ["decriptare cu chei"], b: ["decriptare fără chei"] } },
  470: { note: "Decoiul începe cu \"Steganografia\" în loc de \"Criptografia\"; criptologia are ca laturi criptografia și criptanaliza.", optionHighlights: { a: ["Criptografia"], b: ["Steganografia"] } },
