  489: { note: "Întrebare cu negație (care NU este principiu): corect este \"Minimizarea\" cheii, decoiul opus fiind \"Mărimea\" cheii, care chiar e principiu.", optionHighlights: { a: ["Mărimea"], c: ["Minimizarea"] } },
  490: { note: "Variantele diferă doar prin operator: corect este egalitatea \")=H\" (H(X/C)=H(K)), capcanele fiind \")>H\", \")<H\" și \")<=H\".", optionHighlights: { a: [")>H"], b: [")<H"], c: [")<=H"], d: [")=H"] } },
  493: { note: "Variantele aproape identice diferă prin ce nu se cunoaște: corect este fără sistem și fără cheie (\"utilizat și cheia\"), iar decoii adaugă \"dar cunoscând sistemul\", \"dar cunoscând cheia\" sau \"având cunoștințe\".", optionHighlights: { a: ["dar cunoscând sistemul"], b: ["utilizat și cheia"], c: ["dar cunoscând cheia"], d: ["având cunoștințe"] } },
