  500: { note: "Corect este doar \"Baudot;\"; decoii adaugă \"Morse;\", iar între ei diferența fină este \"Baudot și\" față de \"Baudot sau\".", optionHighlights: { a: ["Baudot;"], b: ["Morse;"], c: ["Baudot și"], d: ["Baudot sau"] } },
