  506: { note: "Diferența este un singur prefix: corect \"Criptarea asimetrică\", decoiul aproape identic fiind \"Criptarea simetrică\".", optionHighlights: { a: ["Criptarea asimetrică"], b: ["Criptarea simetrică"] } },
  509: { note: "Variantele diferă doar prin valoarea numerică a entropiei: corect \"1 bit\"/eveniment, decoii fiind \"0 bit\", \"2 bit\" și \"1/2 bit\".", optionHighlights: { a: ["1 bit"], b: ["0 bit"], c: ["2 bit"], d: ["1/2 bit"] } },
  512: { note: "Are exact aceleași variante de răspuns ca întrebarea despre codificarea neuniformă; aici e vorba de \"codificării redundante\" (protecție la erori, deci cu perturbații), iar decoiul diferă prin \"canalelor cu perturbații\" față de \"canalelor fără perturbații\".", searchQuery: "Tehnica de protectie la erori a canalelor", optionHighlights: { c: ["canalelor cu perturbații"], d: ["canalelor fără perturbații"] }, stemHighlights: ["codificării redundante"] },
