  514: { note: "Răspunsul corect foloseşte indexul \"images[0]\" (prima imagine), iar decoiul foloseşte \"images[1]\" (a doua imagine). Singura diferenţă este cifra indexului.", optionHighlights: { c: ["images[1]"], d: ["images[0]"] } },
  517: { note: "Enunţ aproape identic cu alte variante similare. Aici se cere afirmaţia „care \"dintre\" ... \"este adevărată\"” (singular, afirmativ), nu „sunt adevărate” şi nici „nu este adevărată”.", searchQuery: "Care dintre următoarele afirmații", stemHighlights: ["dintre", "este adevărată"] },
