  530: { note: "Răspunsul corect apelează clasa prin atributul \"class=\"nume\", iar decoiul foloseşte \"id=\"nume\". Diferenţa este doar atributul (class faţă de id).", optionHighlights: { a: ["id=\"nume"], b: ["class=\"nume"] } },
  532: { note: "Enunţ aproape identic cu o variantă similară. Aici se cere afirmaţia care „\"sunt adevărate\"” (afirmativ), pe când perechea ei cere afirmaţiile care nu sunt adevărate (negativ).", searchQuery: "Care afirmaţii sunt adevărate", stemHighlights: ["sunt adevărate"] },
