  539: { note: "Răspunsul corect afişează \"05.70\" (două zecimale impuse de %05.2f), iar decoiul are \"05.7\" (lipseşte ultima zecimală). Diferenţa este zeroul final.", optionHighlights: { b: ["05.70"], d: ["05.7"] } },
  544: { note: "Răspunsul corect foloseşte acolade, „\"{proprietate\"\": valoare\"”, iar decoiul foloseşte punct şi „\".proprietate\"\"= valoare\"” (sintaxă de tip JavaScript). Diferenţa stă în separatori.", optionHighlights: { a: ["{proprietate", ": valoare"], c: [".proprietate", "= valoare"] } },
  547: { note: "Enunţ aproape identic cu alte variante similare, toate despre afişarea „Hello World”. Aici se cere „\"sintaxa corectă Javascript\"” generală, nu varianta cu alert şi nici cea PHP.", searchQuery: "sintaxa corectă Javascript pentru a scrie", stemHighlights: ["sintaxa corectă Javascript"] },
  548: { note: "Enunţ aproape identic cu alte variante similare (toate „Hello World”): aici se cere afişarea „\"într-o fereastra alert\"”. La opţiuni, corect e \"alert(\"...), iar decoiul are \"alert=(\"...), o atribuire greşită.", searchQuery: "Hello World într-o fereastra alert", optionHighlights: { b: ["alert=("], d: ["alert(\""] }, stemHighlights: ["într-o fereastra alert"] },
